'use client'

import { useStrings, type StringsOverrides } from './strings'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Nav, and `tsc --noEmit` passes on it, so the
// gate cannot catch it.
import './nav.css'

// And the shared rule sets, which carry the theme's press gesture. Every
// destination applies `.gs-pressable`, and without this import a customer
// receives the file and the class matches nothing. See
// ./gamestage-primitives.css. GSUI-118.
import './gamestage-primitives.css'
import { LockGlyph } from './glyphs'

// Pressed while a finger is down, set from pointer events. iOS Safari does not
// apply `:active` to an element with no touch listener of its own, so without
// this a raised control never went down under a thumb (Tom, 2026-09-27). Set
// on the element directly: React does not own this attribute, so nothing
// re-renders on every touch. `.gs-pressable[data-gs-pressed='true']` in
// gamestage-primitives.css draws it, and leaves a disabled control still.
const UNPRESSABLE = ":disabled, [aria-disabled='true'], [data-gs-disabled='true'], [data-gs-locked='true']"
const pressHandlers = {
  onPointerDown: (event: React.PointerEvent<HTMLElement>) => {
    // A disabled or locked control does not move: the padlock answers instead.
    if (event.currentTarget.matches(UNPRESSABLE)) return
    event.currentTarget.setAttribute('data-gs-pressed', 'true')
  },
  onPointerUp: (event: React.PointerEvent<HTMLElement>) => event.currentTarget.removeAttribute('data-gs-pressed'),
  onPointerCancel: (event: React.PointerEvent<HTMLElement>) => event.currentTarget.removeAttribute('data-gs-pressed'),
  onPointerLeave: (event: React.PointerEvent<HTMLElement>) => event.currentTarget.removeAttribute('data-gs-pressed'),
}


/**
 * Nav: the places a player can go from here.
 *
 * Specimen 5a. Four presentations of one component: a bar at the foot of the
 * screen with a mark over each word, a strip of tabs with a rule under the
 * current one, a tray of pills, and a drawer of rows that can say why a place
 * is shut. A fifth, `glass`, is the bar as a floating translucent capsule in
 * the manner of the iOS tab bar, with a lens that slides to the current place.
 * Tom, 2026-09-27.
 *
 * Each destination rides on `data-gs-nav`, which is deliberately not
 * `data-gs-choice` and not `data-gs-item`: a test counting the options in a
 * question must not also count a nav bar, and browsing a collection is a third
 * thing again. `data-gs-active` is where the player is, which is not
 * `data-gs-selected`, because a destination is not a pick the player may
 * reverse.
 *
 * It performs nothing. It does not navigate, change a route, or decide which
 * destination is current. `onNavigate` reports the press and the host owns
 * everything behind it, including which one is active on the next render.
 */

export interface Destination {
  /** The host's own id. Rides on `data-gs-nav` and comes back to `onNavigate`. */
  id: string
  /** The word a player reads, and the accessible name whatever the treatment. */
  label: string
  /** The mark for it. Inline SVG taking `currentColor`, never a colour emoji. */
  icon?: React.ReactNode
  /** Where the player is now. */
  active?: boolean
  /** Not available at all. Goes flat and takes no focus. */
  disabled?: boolean
  /** Available later, not now. Keeps its shape, shows a padlock, stays focusable. */
  locked?: boolean
  /**
   * Why it refuses, in words: "opens Friday", "closed". Rendered beside the
   * label as the `note` part and read into the accessible name. The
   * reason lives here and never in the label, so the label stays the name of
   * the place. Shown in the drawer, where a row has the room for it.
   */
  note?: string
}

export interface NavProps
  extends Omit<React.HTMLAttributes<HTMLElement>, 'children' | 'onSelect'> {
  /** Per-instance vocabulary, merged over the provider. */
  strings?: StringsOverrides

  /** The places, in the order they are shown. */
  destinations: Destination[]
  /**
   * Which treatment is rendering.
   *
   * `bar` is the foot of the screen, marks with the words underneath; four
   * destinations at most before it drops the words. `tabs` is a strip with a
   * rule under the current one. `pills` is a tray of rounded controls that
   * scrolls sideways. `drawer` is a vertical list whose rows carry a note.
   * `glass` is the bar as a floating, translucent capsule over the scene, with
   * a lens that slides to the current destination; where the browser cannot
   * blur what is behind it, or the player asks for less transparency, it falls
   * back to a solid capsule.
   *
   * `floating` is a dark capsule held above the bottom edge and the safe area,
   * inset from the sides: the current destination is a lighter pill with its
   * mark and its word, every other one is its mark alone. It reserves its own
   * height in the page, so nothing scrolls out of reach behind it. Tom,
   * 2026-09-27, after the Ringers taster.
   */
  presentation?: 'bar' | 'tabs' | 'pills' | 'drawer' | 'glass' | 'floating'
  /**
   * What `floating` is made of. `solid` is an opaque dark capsule; `glass` is
   * frosted, over the scene, and falls back to solid where the browser cannot
   * blur or the player asks for less transparency. Ignored by the others.
   */
  material?: 'solid' | 'glass'
  /** Where it sits within its container. */
  placement?: 'top' | 'bottom' | 'left' | 'right'
  /** Called with the destination's id. The component navigates nothing itself. */
  onNavigate?: (id: string) => void
  /** The word a player reads as this nav's name. */
  label?: string
  /**
   * `hidden` draws the marks alone: each destination's label stays its
   * accessible name and becomes a hover tooltip on a pointer that can hover.
   * Every destination needs an `icon`. Tom, 2026-09-27: "change the mobile nav
   * to be icon only no words". `shown` by default, except `floating`, which is
   * marks alone unless it is given `shown`.
   */
  labels?: 'shown' | 'hidden'
}

/** From the contract's table of state words, so no component invents its own. */

export function Nav(props: NavProps) {
  const { strings, ...componentProps } = props
  const copy = useStrings(strings)
  const STATE_WORD = {
    active: copy['nav.current'],
    locked: copy['nav.locked'],
  } as const
  const {
    destinations,
    presentation = 'bar',
    placement,
    onNavigate,
    label = copy['nav.label'],
    labels: labelsProp,
    material = 'solid',
    className,
    ...rest
  } = componentProps

  // Where the glass lens sits: the current destination's position in the row.
  // Carried as custom properties so the slide is a CSS transition between two
  // values, and a host re-rendering with a new active id moves it for free.
  const activeIndex = destinations.findIndex((d) => d.active)
  const glass = presentation === 'glass'
  const floating = presentation === 'floating'
  // The floating pill is marks alone by default, the current place included:
  // Tom, 2026-09-28, "NOT label the nav when you click it, just show it
  // highlighted". `labels="shown"` gives a floating nav its current word back.
  const labels = labelsProp ?? (floating ? 'hidden' : 'shown')
  const lensStyle = {
    '--gs-nav-count': String(Math.max(destinations.length, 1)),
    '--gs-nav-index': String(Math.max(activeIndex, 0)),
  } as React.CSSProperties

  // Floating centres itself, and its width comes from the current word, whose
  // width is a fraction of a pixel. Centred on a half pixel, every mark in the
  // capsule landed between two pixels and read soft on a 1x screen (Tom,
  // 2026-09-28, "blurred icons"). So the word is held to a whole pixel, and one
  // more when centring would still land on a half.
  const navRef = React.useRef<HTMLElement>(null)
  React.useLayoutEffect(() => {
    const el = navRef.current
    if (!floating || !el) return
    // The word's own width, read from its text so a min-width already set on
    // it does not feed back into the measure.
    const textWidth = (label: HTMLElement) => {
      const range = document.createRange()
      range.selectNodeContents(label)
      // A test DOM has no layout and no Range geometry; nothing to snap there.
      return typeof range.getBoundingClientRect === 'function' ? range.getBoundingClientRect().width : label.scrollWidth
    }
    const snap = () => {
      const label = el.querySelector<HTMLElement>('[data-gs-active="true"] .gs-nav__label')
      el.querySelectorAll<HTMLElement>('.gs-nav__label').forEach((other) => {
        if (other !== label && other.style.minWidth) other.style.minWidth = ''
      })
      if (labels === 'hidden') {
        // Marks alone: every place is a whole 56px, so only the centring can
        // land on a half. One pixel of padding at the end puts it back.
        const pad = (v: string) => {
          if (el.style.paddingInlineEnd !== v) el.style.paddingInlineEnd = v
        }
        pad('')
        const left = el.getBoundingClientRect().left
        if (Math.abs(left - Math.round(left)) > 0.01) pad('7px')
        return
      }
      if (!label) return
      const base = Math.ceil(textWidth(label))
      const set = (w: number) => {
        if (label.style.minWidth !== `${w}px`) label.style.minWidth = `${w}px`
      }
      set(base)
      const left = el.getBoundingClientRect().left
      if (Math.abs(left - Math.round(left)) > 0.01) set(base + 1)
    }
    snap()
    // Again whenever anything that decides where the capsule lands changes:
    // the page, the capsule's own box, the box it is centred in, or a web font
    // arriving after first paint. Points sat on a half pixel because its
    // container settled after the first snap. Setting the same width again is
    // a no-op, so the observer cannot feed itself.
    document.fonts?.ready.then(snap).catch(() => {})
    if (typeof ResizeObserver === 'undefined') return
    const observer = new ResizeObserver(() => snap())
    observer.observe(document.documentElement)
    observer.observe(el)
    if (el.parentElement) observer.observe(el.parentElement)
    return () => observer.disconnect()
  }, [floating, activeIndex, labels, destinations])

  // The clearance a page needs at its foot so its last line scrolls clear of
  // the capsule, measured rather than assumed: the capsule's own height, the
  // gap under it (which already holds the home bar), and one gap above it.
  // Written to --gs-nav-clearance on :root, kept current as the capsule
  // resizes, and removed when it unmounts. Tom, 2026-09-28: the pill covered
  // Stat Attack's Guess button, because a page padded by a constant is a page
  // that is wrong the first time the capsule is a different height.
  React.useLayoutEffect(() => {
    const el = navRef.current
    if (!floating || !el || typeof window === 'undefined') return
    const root = document.documentElement
    const write = () => {
      const style = getComputedStyle(el)
      const below = parseFloat(style.bottom) || 0
      const gap = parseFloat(style.getPropertyValue('--gs-floating-gap')) || 12
      const height = el.getBoundingClientRect().height
      if (!height) return
      const value = `${Math.ceil(height + below + gap)}px`
      if (root.style.getPropertyValue('--gs-nav-clearance') !== value) root.style.setProperty('--gs-nav-clearance', value)
    }
    write()
    const observer = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(write)
    observer?.observe(el)
    observer?.observe(root)
    window.addEventListener('resize', write)
    return () => {
      observer?.disconnect()
      window.removeEventListener('resize', write)
      root.style.removeProperty('--gs-nav-clearance')
    }
  }, [floating])

  const nav = (
    <nav
      {...rest}
      ref={navRef}
      className={['gs-nav', className].filter(Boolean).join(' ')}
      data-gs-component="nav"
      data-gs-presentation={presentation}
      data-gs-placement={placement}
      data-gs-labels={labels === 'hidden' ? 'hidden' : undefined}
      data-gs-material={floating ? material : undefined}
      aria-label={label}
      style={glass || floating ? { ...lensStyle, ...rest.style } : rest.style}
    >
      {(glass || (floating && labels === 'hidden')) && activeIndex >= 0 ? (
        // Decoration only: the current destination already says so in its
        // name and aria-current. No part name, because it carries no state a
        // test or a screen reader needs; it is the glass catching the light.
        <span className="gs-nav__lens" aria-hidden="true" />
      ) : null}
      <div className="gs-nav__list" data-gs-scope="nav" data-gs-part="list">
        {destinations.map((destination) => {
          // Locked keeps its place in the tab order: "available later" is
          // something a player should be able to reach and hear described.
          // Only disabled, which is not coming back on this surface, leaves.
          // Disabled wins when both are set, the same way button resolves it.
          const isLocked = Boolean(destination.locked) && !destination.disabled
          const unpressable = Boolean(destination.disabled) || isLocked

          // The name carries the state and the reason, because a screen reader
          // user gets no fill, no rule, no padlock and no note.
          const words = [destination.label]
          if (destination.active) words.push(STATE_WORD.active)
          if (isLocked) words.push(STATE_WORD.locked)
          if (destination.note) words.push(destination.note)

          return (
            <button
              key={destination.id}
              type="button"
              // No `gs-action-type`: 5a draws every nav label in the interface
              // face at the label weight, never in the action face. The
              // exemption and its reason are in tests/lib/check-theme-axes.mjs.
              className="gs-nav__destination gs-pressable"
              {...pressHandlers}
              data-gs-scope="nav" data-gs-part="destination"
              data-gs-nav={destination.id}
              data-gs-active={destination.active ? 'true' : undefined}
              data-gs-disabled={destination.disabled ? 'true' : undefined}
              data-gs-locked={isLocked ? 'true' : undefined}
              // The control travels on press, so it is motion and stops dead
              // under reduced motion. The current treatment is colour, a plate
              // and a rule, which are emphasis and survive.
              data-gs-animates="motion"
              aria-current={destination.active ? 'page' : undefined}
              aria-disabled={unpressable ? 'true' : undefined}
              aria-label={words.join(', ')}
              // With no words drawn, the word is the tooltip. A title shows on
              // hover only, so a phone never sees it.
              title={labels === 'hidden' ? destination.label : undefined}
              // aria-disabled does not stop an event the way the native
              // attribute does, so an unpressable destination refuses it here.
              // The native attribute is not used, because a disabled button is
              // unreachable and a locked one must stay describable.
              onClick={unpressable ? undefined : () => onNavigate?.(destination.id)}
            >
              {/* The destination's own mark carries no part. `glyph` is
                  reserved for the mark that carries a state without colour,
                  and a home icon is decoration: naming it `glyph` would stop a
                  selector for that part meaning "a state landed here". */}
              {destination.icon ? (
                <span className="gs-nav__icon" aria-hidden="true">
                  {destination.icon}
                </span>
              ) : null}
              {/* aria-hidden: the button's own label above is the accessible
                  name, and announcing the word again would read it twice. */}
              <span className="gs-nav__label" data-gs-scope="nav" data-gs-part="label" aria-hidden="true">
                {destination.label}
              </span>
              {destination.note ? (
                <span className="gs-nav__note" data-gs-scope="nav" data-gs-part="note" aria-hidden="true">
                  {destination.note}
                </span>
              ) : null}
              {isLocked ? (
                <span
                  className="gs-nav__lock"
                  data-gs-scope="nav" data-gs-part="glyph"
                  // Emphasis, not motion: the padlock is what a reduced-motion
                  // player reads instead of the control refusing to travel.
                  data-gs-animates="emphasis"
                  aria-hidden="true"
                >
                  <LockGlyph />
                </span>
              ) : null}
            </button>
          )
        })}
      </div>
    </nav>
  )

  // Floating holds itself over the page. A page marked `data-gs-page` runs
  // under it to the bottom edge and keeps --gs-nav-clearance, measured above,
  // as padding at its end (nav.css). A host that marks no page gets the old spacer instead, so its
  // last lines still scroll clear without it knowing how tall the capsule is.
  return floating ? (
    <>
      <div className="gs-nav__spacer" aria-hidden="true" />
      {nav}
    </>
  ) : (
    nav
  )
}

/* Nav, as specimen 5a draws it. Every value comes from a token; nothing here
   is a literal colour, size, radius, duration or typeface. The one number is
   the note's opacity, which has no token and is a request (see the report on
   GSUI-201).

   The press gesture comes from `.gs-pressable` in packages/tokens/primitives.css,
   which every destination carries. The action type does not: 5a draws every nav
   label in the interface face at the label weight (12/800 in the bar, 14 to
   16/800 in the pills, tabs and drawer), never in the action face, so the
   destination reads the label tokens directly and tests/lib/check-theme-axes.mjs
   carries the exemption with that reason.

   Two private properties carry the idle face, because it differs by
   presentation: a bar or a tab destination at rest is bare, a pill or a drawer
   row at rest is a surface plate with an edge. The state rules below then only
   have to say what changes. */

.gs-nav {
  --gs-nav-idle-fill: var(--gs-color-surface);
  --gs-nav-idle-edge: var(--gs-color-edge);

  display: flex;
  align-items: stretch;
  gap: var(--gs-space-2);
  box-sizing: border-box;
  padding: var(--gs-space-2);
  color: var(--gs-color-ink);
  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-xl);
}

/* The list is the group a screen reader hears and the handle a test finds. It
   is not a box: the drawing lays destinations straight into the container, so
   the container is the flex parent and the list contributes no box of its own. */
.gs-nav__list {
  display: contents;
}

.gs-nav__destination {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--gs-space-2);
  box-sizing: border-box;
  margin: 0;
  padding: 0 var(--gs-space-3);

  /* The label tokens, and only their face, size and weight. The drawing types
     every destination in sentence case with no tracking, so the label's
     uppercase and letter-spacing are deliberately not read. */
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  line-height: normal;

  color: var(--gs-color-ink-secondary);
  background: var(--gs-nav-idle-fill);
  border: var(--gs-stroke-ui) solid var(--gs-nav-idle-edge);
  border-radius: var(--gs-radius-md);
  cursor: pointer;
}

/* At rest a destination squeezes on press and casts nothing. Only the current
   one rides on the theme's offset base, and it keeps the gesture the primitives
   hand every pressable. Restated under reduced motion below, because a value
   set here beats the primitives' own reduced-motion rule. */
.gs-nav__destination:not([data-gs-active='true']) {
  --gs-press-transform: var(--gs-depth-styles-squeeze-transform);
  --gs-depth-pressable-pressed: none;
}

.gs-nav__icon,
.gs-nav__lock,
.gs-nav__note {
  display: flex;
  line-height: 1;
}

.gs-nav__icon {
  font-size: var(--gs-size-icon-control);
}

/* The padlock is the mark that carries a state, so it is emphasis and keeps
   its transition under reduced motion. It draws at the label size, 1em, which
   is the 12px the bar draws; below 14px a mark needs the small stroke or it
   greys out into its own antialiasing (glyphs.css). */
.gs-nav__lock {
  transition: opacity var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

.gs-nav__lock .gs-glyph {
  stroke-width: var(--gs-stroke-glyph-small);
}

.gs-nav__label {
  white-space: nowrap;
}

/* Why a destination refuses, in words, beside the label and never in it. Same
   ink as the row, stepped back. */
.gs-nav__note {
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  white-space: nowrap;
  opacity: 0.8;
}

.gs-nav__destination:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-selected);
  outline-offset: var(--gs-space-1);
}

/* The ring is for a keyboard only. A tap or a click that leaves focus on a
   destination draws nothing: Tom saw a thick teal ring round the pill after a
   tap (2026-09-28). */
.gs-nav__destination:focus:not(:focus-visible) {
  outline: none;
}

/* -- bar: the foot of the screen ------------------------------------------ */
/* A surface with an edge along its top and nothing else: no radius, no side
   or bottom stroke. Destinations share the width, icon over word. */
.gs-nav[data-gs-presentation='bar'] {
  --gs-nav-idle-fill: transparent;
  --gs-nav-idle-edge: transparent;

  width: 100%;
  border-width: 0;
  border-top-width: var(--gs-stroke-ui);
  border-radius: 0;
}

.gs-nav[data-gs-presentation='bar'] .gs-nav__destination {
  flex: 1 1 0;
  flex-direction: column;
  gap: var(--gs-space-1);
  min-width: 0;
  height: var(--gs-size-action-large);
  padding: 0;
}

.gs-nav[data-gs-presentation='bar'] .gs-nav__label {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* A bar never ellipsises a word. Four destinations of six characters fit at
   390px; a fifth does not, so from five the bar drops its words and shows the
   marks alone. The accessible name is on the control and is unaffected. */
.gs-nav[data-gs-presentation='bar'] .gs-nav__list:has(> :nth-child(5)) .gs-nav__label {
  display: none;
}

.gs-nav[data-gs-presentation='bar'] .gs-nav__lock {
  position: absolute;
  top: var(--gs-space-2);
  right: var(--gs-space-2);
}

/* -- tabs: a rule under the current one ----------------------------------- */
/* No fill and no radius. The strip carries a rule along its foot; the current
   tab carries a thicker one that sits on it. Every tab squeezes on press. */
.gs-nav[data-gs-presentation='tabs'] {
  --gs-nav-idle-fill: transparent;
  --gs-nav-idle-edge: transparent;

  gap: var(--gs-space-1);
  padding: 0;
  background: none;
  border-width: 0;
  border-bottom-width: var(--gs-stroke-ui);
  border-radius: 0;
}

.gs-nav[data-gs-presentation='tabs'] .gs-nav__destination {
  --gs-press-transform: var(--gs-depth-styles-squeeze-transform);
  --gs-depth-pressable-pressed: none;

  /* Never narrower than its words: equal tabs sized from the widest left the
     others a few pixels short, and "Board" became "Boa...". If the row then
     outgrows its container the nav overflows, which is visible and fixable. */
  min-width: max-content;
  height: var(--gs-size-touch-min);
  padding: 0 var(--gs-space-3);
  margin-bottom: calc(-1 * var(--gs-stroke-ui));
  border-width: 0;
  border-bottom-width: var(--gs-stroke-selected);
  border-radius: 0;
}

.gs-nav[data-gs-presentation='tabs'] .gs-nav__icon,
.gs-nav[data-gs-presentation='pills'] .gs-nav__icon {
  font-size: var(--gs-size-icon-utility);
}

/* -- pills: a tray of rounded controls ------------------------------------ */
/* The tray is a pill itself, sized to its contents and scrolling sideways when
   they outgrow the screen. A pill at rest is a surface plate with an edge. */
.gs-nav[data-gs-presentation='pills'] {
  width: max-content;
  max-width: 100%;
  overflow-x: auto;
  scrollbar-width: none;
  border-radius: var(--gs-radius-full);
}

.gs-nav[data-gs-presentation='pills'] .gs-nav__destination {
  flex: none;
  height: var(--gs-size-control-small);
  padding: 0 var(--gs-space-3);
  border-radius: var(--gs-radius-full);
}

/* -- drawer: a vertical list ---------------------------------------------- */
.gs-nav[data-gs-presentation='drawer'] {
  flex-direction: column;
  align-items: stretch;
}

.gs-nav[data-gs-presentation='drawer'] .gs-nav__destination {
  flex: none;
  /* The row does not centre: the label takes the room and pushes the note and
     the padlock to the right, as the drawing lays it out. */
  justify-content: normal;
  gap: var(--gs-space-3);
  width: 100%;
  height: var(--gs-size-action);
  padding: 0 var(--gs-space-3);
}

.gs-nav[data-gs-presentation='drawer'] .gs-nav__label {
  flex: 1;
  text-align: left;
}

/* -- where the player is -------------------------------------------------- */
/* Quiet, since 2026-09-27 (Tom): the current place was a filled interactive
   plate on the theme's base, which shouted louder than the game above it. It
   is now the selection colour on a light tint of itself. Colour is never the
   only signal: the tint is a shape a player can see without seeing the hue,
   the label keeps its weight, and the name says "current" to a screen reader.
   design/twins/5a.json records the departure from the drawing.

   Bar: a tinted capsule behind the mark, the word in the selection colour.
   Pills and drawer: the whole plate tinted, its edge in the selection colour.
   Tabs keep their rule, which was already quiet. Written after the
   presentations at the same specificity so the state wins. */
.gs-nav {
  --gs-nav-accent: var(--gs-color-selected);
  --gs-nav-tint: color-mix(in oklch, var(--gs-nav-accent) 18%, transparent);
}

.gs-nav .gs-nav__destination[data-gs-active='true'] {
  /* The words stay in the ink, which every theme contrasts against its
     surface; the selection colour went on the word at first and read 3.3:1 on
     arcade's blue. The tint and the mark carry the colour instead. */
  color: var(--gs-color-ink);
  background: var(--gs-nav-tint);
  border-color: color-mix(in oklch, var(--gs-nav-accent) 45%, transparent);
  box-shadow: none;
}

/* The bar tints the mark, not the whole column, as a tab bar does. */
.gs-nav[data-gs-presentation='bar'] .gs-nav__destination[data-gs-active='true'] {
  background: transparent;
  border-color: transparent;
}

.gs-nav[data-gs-presentation='bar'] .gs-nav__icon {
  box-sizing: border-box;
  align-items: center;
  justify-content: center;
  width: calc(var(--gs-size-icon-control) * 2.25);
  height: calc(var(--gs-size-icon-control) * 1.3);
  border-radius: var(--gs-radius-full);
  transition: background-color var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

.gs-nav[data-gs-presentation='bar'] .gs-nav__destination[data-gs-active='true'] .gs-nav__icon {
  color: var(--gs-nav-accent);
  background: var(--gs-nav-tint);
}

/* -- glass: the bar as a floating capsule --------------------------------- */
/* After the iOS tab bar: inset from the edges, a capsule of frosted glass over
   whatever the game draws, a bright rim where light catches the edge, and a
   lens that slides to the current place with a little overshoot. Built from
   backdrop-filter, layered gradients and shadows; no Apple assets. Colours
   are the theme's background, white and black mixed to a transparency, never
   a literal, so the qa colour scan holds.

   Dark glass by default, because games run on dark scenes; a host on a light
   scene sets data-gs-tone="light". The host positions it (fixed, above the
   home indicator); the capsule only draws itself. */
.gs-nav[data-gs-presentation='glass'] {
  --gs-nav-idle-fill: transparent;
  --gs-nav-idle-edge: transparent;
  --gs-glass-fill: color-mix(in oklch, var(--gs-color-background) 52%, transparent);
  --gs-glass-rim: color-mix(in srgb, white 22%, transparent);
  --gs-glass-sheen: color-mix(in srgb, white 10%, transparent);
  --gs-glass-lens: color-mix(in srgb, white 14%, transparent);
  --gs-glass-lens-rim: color-mix(in srgb, white 28%, transparent);
  --gs-glass-shadow: 0 10px 30px color-mix(in srgb, black 35%, transparent), 0 2px 6px color-mix(in srgb, black 20%, transparent);
  --gs-glass-ink: color-mix(in srgb, white 62%, transparent);
  /* Always a capsule, whatever the theme's corners: paper squares its
     radius.full, and a squared glass bar stops reading as the iOS one. */
  --gs-glass-radius: 999px;

  position: relative;
  isolation: isolate;
  gap: 0;
  /* Sized to its tabs and centred, as iOS draws it, never wider than the
     screen less its gutters. */
  width: fit-content;
  max-width: calc(100% - 2 * var(--gs-space-4));
  margin-inline: auto;
  padding: 4px;
  color: var(--gs-glass-ink);
  background:
    linear-gradient(180deg, var(--gs-glass-sheen), transparent 55%),
    var(--gs-glass-fill);
  border: 0.5px solid var(--gs-glass-rim);
  border-radius: var(--gs-glass-radius, 999px);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, white 18%, transparent),
    inset 0 -1px 0 color-mix(in srgb, black 10%, transparent),
    var(--gs-glass-shadow);
  -webkit-backdrop-filter: blur(22px) saturate(1.8);
  backdrop-filter: blur(22px) saturate(1.8);
}

.gs-nav[data-gs-presentation='glass'][data-gs-tone='light'] {
  --gs-glass-fill: color-mix(in srgb, white 62%, transparent);
  --gs-glass-rim: color-mix(in srgb, white 65%, transparent);
  --gs-glass-sheen: color-mix(in srgb, white 55%, transparent);
  --gs-glass-lens: color-mix(in srgb, black 6%, transparent);
  --gs-glass-lens-rim: color-mix(in srgb, white 90%, transparent);
  --gs-glass-shadow: 0 10px 30px color-mix(in srgb, black 12%, transparent), 0 2px 6px color-mix(in srgb, black 8%, transparent);
  --gs-glass-ink: color-mix(in srgb, black 78%, transparent);
}

.gs-nav[data-gs-presentation='glass'] .gs-nav__destination {
  z-index: 1;
  flex: 1 1 0;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  width: 88px;
  height: 54px;
  padding: 0;
  color: inherit;
  border-width: 0;
  border-radius: var(--gs-glass-radius, 999px);
  /* iOS sets tab labels at 10pt; the one type scale's smallest step is 14,
     the floor for anything a fan reads (GSUI-292). */
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-nav-label-weight);
  letter-spacing: 0.01em;
}

.gs-nav[data-gs-presentation='glass'] .gs-nav__icon {
  font-size: var(--gs-size-icon-control);
}

.gs-nav[data-gs-presentation='glass'] .gs-nav__label {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
}

.gs-nav[data-gs-presentation='glass'] .gs-nav__destination[data-gs-active='true'] {
  /* Glass has its own fixed backdrops, dark and light, so the accent is
     checked against those rather than the theme's surface. */
  color: var(--gs-nav-accent);
  background: transparent;
  border-color: transparent;
}

/* The lens: a smaller capsule of brighter glass behind the current place,
   sliding between places with a spring. Its position comes from the two
   custom properties the component sets on the nav. */
.gs-nav__lens {
  position: absolute;
  z-index: 0;
  top: 4px;
  bottom: 4px;
  left: 4px;
  width: calc((100% - 8px) / var(--gs-nav-count, 1));
  border-radius: var(--gs-glass-radius, 999px);
  background:
    radial-gradient(120% 90% at 50% 0%, color-mix(in srgb, white 16%, transparent), transparent 60%),
    var(--gs-glass-lens);
  box-shadow:
    inset 0 0 0 0.5px var(--gs-glass-lens-rim),
    inset 0 1px 1px color-mix(in srgb, white 25%, transparent),
    0 1px 4px color-mix(in srgb, black 15%, transparent);
  transform: translateX(calc(100% * var(--gs-nav-index, 0)));
  /* The pop curve overshoots and settles, which is the spring a tab bar lens
     has; the reorder duration is what a sliding element takes here. */
  transition: transform var(--gs-motion-reorder) var(--gs-motion-ease-pop);
  pointer-events: none;
}

.gs-nav[data-gs-presentation='glass'] .gs-nav__destination:not([data-gs-active='true']):active {
  --gs-press-transform: scale(0.94);
}

/* Where the browser cannot blur what is behind, or the player asks for less
   transparency, the capsule goes solid rather than showing the scene through a
   clear pane. */
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .gs-nav[data-gs-presentation='glass'] {
    background: var(--gs-color-surface-raised, var(--gs-color-surface));
  }
}

@media (prefers-reduced-transparency: reduce) {
  .gs-nav[data-gs-presentation='glass'] {
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
    background: var(--gs-color-surface-raised, var(--gs-color-surface));
    color: var(--gs-color-ink-secondary);
  }
}

@media (prefers-reduced-motion: reduce) {
  .gs-nav__lens {
    transition: none;
  }
}

/* -- floating: a dark capsule held above the bottom edge ------------------- */
/* After the Ringers taster (Tom, 2026-09-27). The capsule is inset from the
   sides and sits above the safe area; the current place is a lighter pill with
   its mark and its word, every other place is its mark alone. So the current
   place is told by shape and a word as well as by a lighter fill.

   It carries its own dark pair, as glass does, rather than reading the theme's
   surface: a dark capsule is the drawing on light and dark scenes alike, and a
   fixed pair is one that can be proved for contrast once. data-gs-tone="light"
   flips it for a host that wants a pale capsule. */
.gs-nav[data-gs-presentation='floating'] {
  --gs-floating-fill: oklch(0.2 0.012 275);
  --gs-floating-ink: oklch(0.985 0 0);
  --gs-floating-ink-idle: color-mix(in oklch, oklch(0.985 0 0) 72%, transparent);
  --gs-floating-pill: color-mix(in oklch, oklch(0.985 0 0) 16%, transparent);
  --gs-floating-shadow: 0 12px 32px color-mix(in srgb, black 30%, transparent), 0 2px 8px color-mix(in srgb, black 18%, transparent);
  --gs-floating-height: 64px;
  --gs-floating-gap: var(--gs-space-3, 12px);

  position: fixed;
  z-index: 50;
  inset-inline: 0;
  bottom: calc(env(safe-area-inset-bottom, 0px) + var(--gs-floating-gap));
  gap: 2px;
  width: fit-content;
  max-width: calc(100% - 2 * var(--gs-space-4, 16px));
  height: var(--gs-floating-height);
  margin-inline: auto;
  padding: 6px;
  color: var(--gs-floating-ink-idle);
  background: var(--gs-floating-fill);
  border: 0;
  border-radius: 999px;
  box-shadow: var(--gs-floating-shadow);
}

.gs-nav[data-gs-presentation='floating'][data-gs-tone='light'] {
  --gs-floating-fill: oklch(0.985 0 0);
  --gs-floating-ink: oklch(0.2 0.012 275);
  --gs-floating-ink-idle: color-mix(in oklch, oklch(0.2 0.012 275) 72%, transparent);
  --gs-floating-pill: color-mix(in oklch, oklch(0.2 0.012 275) 9%, transparent);
  --gs-floating-shadow: 0 12px 32px color-mix(in srgb, black 14%, transparent), 0 2px 8px color-mix(in srgb, black 8%, transparent);
}

/* The page runs to the bottom edge and the capsule floats over it. Tom,
   2026-09-28, on Stat Attack: "the UI on mobile should go behind the nav to
   the bottom". A reserved strip under the page left a band of background
   between the last card and the capsule.

   So the page's scroll area, marked data-gs-page, fills the screen to its foot
   and keeps the capsule's clearance as padding at its end instead: its height,
   its gap above the edge and a gap above it, and the home bar. Scrolled to the
   end, the last line sits clear of the capsule; at rest, content passes under
   it.

   --gs-nav-clearance is measured by the nav itself and written on :root while
   a floating nav is mounted (nav.tsx), so it is right whatever the capsule's
   height turns out to be. The calc below is only the first paint's value,
   before the nav has measured. A host that lays out its own foot pads by
   var(--gs-nav-clearance, 0px). */
:root:has(.gs-nav[data-gs-presentation='floating']) [data-gs-page] {
  padding-block-end: calc(
    var(--gs-page-end, var(--gs-space-4, 16px)) +
      var(--gs-nav-clearance, calc(var(--gs-floating-height, 64px) + 2 * var(--gs-space-3, 12px) + env(safe-area-inset-bottom, 0px)))
  );
  scroll-padding-block-end: var(--gs-nav-clearance, 0px);
}

/* A host without a marked page keeps the old reservation: a block the
   capsule's height at the foot of wherever the nav sits. */
.gs-nav__spacer {
  display: block;
  height: var(--gs-nav-clearance, calc(var(--gs-floating-height, 64px) + 2 * var(--gs-space-3, 12px) + env(safe-area-inset-bottom, 0px)));
}

:root:has([data-gs-page]) .gs-nav__spacer {
  display: none;
}

.gs-nav[data-gs-presentation='floating'] .gs-nav__destination {
  flex: 0 0 auto;
  gap: 0;
  /* 48px is the smallest tap target the library allows; four marks and a
     worded pill then fit a 360px phone inside its 16px gutters. */
  min-width: 48px;
  height: 100%;
  padding-inline: 12px;
  color: inherit;
  background: transparent;
  border: 0;
  border-radius: 999px;
  font-size: var(--gs-type-action-font-size);
  font-weight: var(--gs-nav-label-weight);
  white-space: nowrap;
  transition:
    background-color var(--gs-motion-reorder) var(--gs-motion-ease-pop),
    color var(--gs-motion-reorder) var(--gs-motion-ease-pop),
    gap var(--gs-motion-reorder) var(--gs-motion-ease-pop),
    transform var(--gs-motion-press) var(--gs-motion-ease-press);
}

.gs-nav[data-gs-presentation='floating'] .gs-nav__icon {
  font-size: var(--gs-size-icon-control);
}

/* Every place but the current one is its mark alone. The word folds away
   rather than vanishing, so the pill reads as moving to the place pressed. */
.gs-nav[data-gs-presentation='floating'] .gs-nav__label {
  display: inline-block;
  max-width: 0;
  overflow: hidden;
  opacity: 0;
  transition:
    max-width var(--gs-motion-reorder) var(--gs-motion-ease-pop),
    opacity var(--gs-motion-reorder) var(--gs-motion-ease-pop);
}

.gs-nav[data-gs-presentation='floating'] .gs-nav__destination[data-gs-active='true'] {
  /* The worded pill is the one place that may give: a long word truncates
     rather than pushing the capsule off the screen. */
  flex: 0 1 auto;
  min-width: 0;
  gap: 8px;
  color: var(--gs-floating-ink);
  background: var(--gs-floating-pill);
  border-color: transparent;
  box-shadow: none;
}

.gs-nav[data-gs-presentation='floating'] .gs-nav__destination[data-gs-active='true'] .gs-nav__label {
  max-width: 12em;
  min-width: 0;
  text-overflow: ellipsis;
  opacity: 1;
}

/* The floating capsule is already the only thing drawn; a press squeezes the
   mark, it does not drop a shelf that is not there. */
.gs-nav[data-gs-presentation='floating'] .gs-nav__destination:active,
.gs-nav[data-gs-presentation='floating'] .gs-nav__destination[data-gs-pressed='true'] {
  --gs-press-transform: scale(0.94);
  box-shadow: none;
}

.gs-nav[data-gs-presentation='floating'][data-gs-labels='hidden'] .gs-nav__destination[data-gs-active='true'] .gs-nav__label {
  display: none;
}

/* The bar's underline mark is not the pill's: the pill's current place is its
   highlight, and the mark drew a stray bar under it (Tom, 2026-09-28). */
/* Marks alone, the default: every place the same width, so nothing moves
   when the selection does; the current place is the lighter pill sliding
   behind its mark and the mark at full strength, never a word or a heavier
   mark. The word stays each place's name and a hover tooltip. */
.gs-nav[data-gs-presentation='floating'][data-gs-labels='hidden'] {
  gap: 0;
}

.gs-nav[data-gs-presentation='floating'][data-gs-labels='hidden'] .gs-nav__destination,
.gs-nav[data-gs-presentation='floating'][data-gs-labels='hidden'] .gs-nav__destination[data-gs-active='true'] {
  flex: 0 0 56px;
  inline-size: 56px;
  min-width: 56px;
  padding-inline: 0;
  gap: 0;
  background: transparent;
}

.gs-nav[data-gs-presentation='floating'][data-gs-labels='hidden'] .gs-nav__label {
  display: none;
}

.gs-nav[data-gs-presentation='floating'][data-gs-labels='hidden'] .gs-nav__lens {
  position: absolute;
  z-index: 0;
  top: 6px;
  bottom: 6px;
  left: 6px;
  width: 56px;
  border-radius: 999px;
  background: var(--gs-floating-pill);
  transform: translateX(calc(56px * var(--gs-nav-index, 0)));
  transition: transform var(--gs-motion-reorder) var(--gs-motion-ease-pop);
  pointer-events: none;
}

.gs-nav[data-gs-presentation='floating'][data-gs-labels='hidden'] .gs-nav__destination {
  position: relative;
  z-index: 1;
}

@media (prefers-reduced-motion: reduce) {
  .gs-nav[data-gs-presentation='floating'][data-gs-labels='hidden'] .gs-nav__lens {
    transition: none;
  }
}

/* Frosted, over the scene. Solid again where the browser cannot blur or the
   player asks for less transparency. */
.gs-nav[data-gs-presentation='floating'][data-gs-material='glass'] {
  --gs-floating-fill: color-mix(in oklch, oklch(0.2 0.012 275) 58%, transparent);
  -webkit-backdrop-filter: blur(22px) saturate(1.8);
  backdrop-filter: blur(22px) saturate(1.8);
  box-shadow:
    inset 0 0 0 0.5px color-mix(in srgb, white 22%, transparent),
    inset 0 1px 0 color-mix(in srgb, white 18%, transparent),
    var(--gs-floating-shadow);
}

.gs-nav[data-gs-presentation='floating'][data-gs-material='glass'][data-gs-tone='light'] {
  --gs-floating-fill: color-mix(in oklch, oklch(0.985 0 0) 66%, transparent);
}

@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .gs-nav[data-gs-presentation='floating'][data-gs-material='glass'] {
    --gs-floating-fill: oklch(0.2 0.012 275);
  }
  .gs-nav[data-gs-presentation='floating'][data-gs-material='glass'][data-gs-tone='light'] {
    --gs-floating-fill: oklch(0.985 0 0);
  }
}

@media (prefers-reduced-transparency: reduce) {
  .gs-nav[data-gs-presentation='floating'][data-gs-material='glass'] {
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
    --gs-floating-fill: oklch(0.2 0.012 275);
  }
  .gs-nav[data-gs-presentation='floating'][data-gs-material='glass'][data-gs-tone='light'] {
    --gs-floating-fill: oklch(0.985 0 0);
  }
}

/* The pill arrives, it does not travel: under reduced motion the word and the
   fill change at once, and the shape and the word still say which place. */
@media (prefers-reduced-motion: reduce) {
  .gs-nav[data-gs-presentation='floating'] .gs-nav__destination,
  .gs-nav[data-gs-presentation='floating'] .gs-nav__label {
    transition: none;
  }
}

/* -- available later, not now --------------------------------------------- */
/* Keeps its shape and shows a padlock: "not yet" against "not ever". */
.gs-nav .gs-nav__destination[data-gs-locked='true'] {
  color: var(--gs-color-ink-secondary);
  background: transparent;
  border-style: dashed;
  border-color: var(--gs-color-edge-high);
  cursor: default;
}

/* -- not available at all ------------------------------------------------- */
/* Flat, per the depth rule, and it does not travel on press. */
.gs-nav .gs-nav__destination[data-gs-disabled='true'] {
  color: var(--gs-color-disabled-ink);
  background: var(--gs-color-disabled);
  border-color: transparent;
  box-shadow: var(--gs-depth-flat);
  cursor: default;
}

/* The current tab. The drawing writes its rule in `reward`, which in arcade is
   a gradient and so an invalid border colour that the browser discards; the
   canvas paints the rule in the ink. The note under the drawing says reward,
   and reward.solid is the token a stroke reads. design/twins/5a.json carries
   the allowance. */
.gs-nav[data-gs-presentation='tabs'] .gs-nav__destination[data-gs-active='true'] {
  color: var(--gs-color-ink);
  background: transparent;
  border-color: var(--gs-color-reward-solid);
  box-shadow: none;
}

/* -- placement ------------------------------------------------------------ */
/* The edge the nav hugs. The host owns the container; a nav on a side runs
   its destinations down rather than across. */
.gs-nav[data-gs-placement='left'],
.gs-nav[data-gs-placement='right'] {
  flex-direction: column;
  align-items: stretch;
}

/* Restated on the element and deliberately last: the squeeze set above beats
   the primitives' own reduced-motion rule, so it has to be zeroed here too. */
/* A destination's press, for a player who has asked for stillness.
 *
 * Every other pressable answers through the shared rule at the bottom of
 * primitives.css, which remaps the edge and the depth tokens. A destination
 * reads neither: it draws from `--gs-nav-idle-fill` and `--gs-nav-idle-edge`,
 * which the bar and the tabs presentations both set to `transparent`, and it
 * casts nothing at all, so with the squeeze gone it answered with nothing.
 * Measured on 20 September. GSUI-164.
 *
 * Specificity is deliberate: `.gs-nav[data-gs-presentation='bar']
 * .gs-nav__destination` is where the transparent values are set, so a rule
 * that only says `.gs-nav__destination:active` would lose to it. */
@media (prefers-reduced-motion: reduce) {
  .gs-nav .gs-nav__destination:active:not([data-gs-disabled='true']):not([data-gs-locked='true']) {
    --gs-nav-idle-fill: var(--gs-color-surface-raised);
    --gs-nav-idle-edge: var(--gs-color-edge-high);
  }
}

@media (prefers-reduced-motion: reduce) {
  /* Matched to the two rules that set the squeeze above, not written at the
     bare class. `.gs-nav__destination:not([data-gs-active='true'])` carries an
     attribute selector and outranks `.gs-nav__destination`, so this rule was
     losing and a destination still squeezed under reduced motion. Measured on
     20 September. GSUI-164. */
  .gs-nav__destination:not([data-gs-active='true']),
  .gs-nav[data-gs-presentation='tabs'] .gs-nav__destination {
    --gs-press-transform: none;
  }
}

/* -- labels hidden: the marks alone ----------------------------------------- */
/* Every destination is at least 48px square to a thumb. The current one says
   so without a word three ways: its mark is filled (a change of shape), it is
   drawn in the accent on a tint, and a short bar sits under it. The mark is
   in the ink, so an idle destination holds the ink's contrast. */
.gs-nav[data-gs-labels='hidden'] .gs-nav__label { display: none; }
.gs-nav[data-gs-labels='hidden'] .gs-nav__destination {
  min-inline-size: 48px;
  min-block-size: 48px;
  touch-action: manipulation;
}
.gs-nav[data-gs-labels='hidden'] .gs-nav__icon { font-size: var(--gs-size-icon-control); }
.gs-nav[data-gs-labels='hidden']:not([data-gs-presentation='floating']) .gs-nav__destination[data-gs-active='true']::after {
  content: '';
  position: absolute;
  inset-block-end: 4px;
  inset-inline-start: 50%;
  inline-size: 16px;
  block-size: 3px;
  margin-inline-start: -8px;
  border-radius: var(--gs-radius-full);
  background: var(--gs-nav-accent);
}

/* -- light marks and words ------------------------------------------------ */
/* Tom, 2026-09-28: "make these light thin icons and fonts". Every nav draws
   its marks as thin outlines and its words at a regular weight; the current
   place is told by its plate or pill and by full-strength colour. Two
   properties, so a theme or a game that wants a heavier nav sets them. */
.gs-nav {
  --gs-nav-stroke: 1.5px;
  /* Regular, one of the scale's two weights (GSUI-292). */
  --gs-nav-label-weight: var(--gs-type-body-font-weight);
}

.gs-nav .gs-nav__icon .gs-glyph {
  stroke-width: var(--gs-nav-stroke);
}

.gs-nav .gs-nav__label,
.gs-nav[data-gs-presentation='floating'] .gs-nav__destination {
  font-weight: var(--gs-nav-label-weight);
}
